from pathlib import Path
p=Path('src/main.jsx');s=p.read_text(encoding='utf-8')
s=s.replace("{screen==='admin'&&profile.role==='admin'&&<Admin p={profile}/>}","{screen==='admin'&&profile.role==='admin'&&<Admin p={profile}/>} {screen==='admin'&&profile.role==='editor'&&<Editor p={profile}/>}",1)
s=s.replace("{p.role==='admin'&&<button className=\"card\" onClick={()=>go('admin')}><Settings/> Administração</button>}","{(p.role==='admin'||p.role==='editor')&&<button className=\"card\" onClick={()=>go('admin')}><Settings/> {p.role==='admin'?'Administração':'Gestão da casa'}</button>}",1)
editor='''function Editor(){\n const[giras,setGiras]=useState([]),[sel,setSel]=useState(null),[tasks,setTasks]=useState([]),[cats,setCats]=useState([]),[form,setForm]=useState({name:\"\",starts_at:\"\",what_to_bring:\"\",contribution_amount:0,contribution_due_date:\"\",notes:\"\"}),[task,setTask]=useState({name:\"\",period_key:\"friday\",slots:1,category_id:\"\"}),[msg,setMsg]=useState(\"\");\n const load=()=>supabase.from(\"giras\").select(\"*\").order(\"starts_at\").then(({data})=>setGiras(data||[]));\n const loadTasks=id=>supabase.from(\"tasks\").select(\"*,task_categories(name)\").eq(\"gira_id\",id).order(\"period_key\").then(({data})=>setTasks(data||[]));\n useEffect(()=>{load();supabase.from(\"task_categories\").select(\"id,name\").order(\"name\").then(({data})=>setCats(data||[]))},[]);\n const open=g=>{setSel(g);setForm({name:g.name,starts_at:new Date(g.starts_at).toISOString().slice(0,16),what_to_bring:g.what_to_bring||\"\",contribution_amount:g.contribution_amount||0,contribution_due_date:g.contribution_due_date||\"\",notes:g.notes||\"\"});loadTasks(g.id)};\n const save=async()=>{const args={p_name:form.name,p_starts_at:new Date(form.starts_at).toISOString(),p_what_to_bring:form.what_to_bring,p_contribution_amount:Number(form.contribution_amount||0),p_contribution_due_date:form.contribution_due_date||null,p_notes:form.notes};if(sel)args.p_gira_id=sel.id;const{error}=await supabase.rpc(sel?\"update_gira\":\"create_gira\",args);setMsg(error?.message||\"Gira salva.\");if(!error){await load();if(sel)loadTasks(sel.id)}};\n const del=async()=>{if(!confirm(\"Excluir esta gira?\"))return;const{error}=await supabase.rpc(\"delete_gira\",{p_gira_id:sel.id});setMsg(error?.message||\"Gira excluída.\");if(!error){setSel(null);load()}};\n const addTask=async()=>{const{error}=await supabase.rpc(\"create_task\",{p_gira_id:sel.id,p_name:task.name,p_period_key:task.period_key,p_slots:Number(task.slots),p_category_id:task.category_id||null});setMsg(error?.message||\"Tarefa criada.\");if(!error){setTask({...task,name:\"\"});loadTasks(sel.id)}};\n const delTask=async id=>{const{error}=await supabase.rpc(\"delete_task\",{p_task_id:id});setMsg(error?.message||\"Tarefa excluída.\");if(!error)loadTasks(sel.id)};\n const draw=async()=>{const{data,error}=await supabase.rpc(\"draw_gira_tasks\",{p_gira_id:sel.id});setMsg(error?.message||`Sorteio concluído: ${data?.assigned||0} atribuições.`)};\n return <><div className=\"hero\"><span className=\"eyebrow\">GESTÃO DA CASA</span><h1>Giras e tarefas</h1><p className=\"muted\">Organize a programação sem acesso ao financeiro.</p></div>{msg&&<div className=\"toast\">{msg}</div>}{!sel?<><button className=\"btn primary\" onClick={()=>{setSel({id:null});setForm({name:\"\",starts_at:\"\",what_to_bring:\"\",contribution_amount:0,contribution_due_date:\"\",notes:\"\"})}}><Plus size={16}/> Nova gira</button><div className=\"list\">{giras.map(g=><button className=\"card gira\" key={g.id} onClick={()=>open(g)}><div className=\"art\">🌿</div><div style={{textAlign:\"left\"}}><h2>{g.name}</h2><p>{dateTime(g.starts_at)}</p></div><ChevronRight style={{marginLeft:\"auto\"}}/></button>)}</div></>:<><button className=\"btn\" onClick={()=>setSel(null)}>← Todas as giras</button><div className=\"card\"><h2>{sel.id?\"Editar gira\":\"Nova gira\"}</h2>{[[\"Nome\",\"name\"],[\"O que levar\",\"what_to_bring\"],[\"Observações\",\"notes\"]].map(([l,k])=><div className=\"field\" key={k}><label>{l}</label><input className=\"input\" value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></div>)}<div className=\"field\"><label>Data e horário</label><input className=\"input\" type=\"datetime-local\" value={form.starts_at} onChange={e=>setForm({...form,starts_at:e.target.value})}/></div><div className=\"field\"><label>Contribuição</label><input className=\"input\" type=\"number\" step=\"0.01\" value={form.contribution_amount} onChange={e=>setForm({...form,contribution_amount:e.target.value})}/></div><button className=\"btn primary\" onClick={save}>Salvar</button>{sel.id&&<button className=\"btn\" onClick={del}>Excluir</button>}</div>{sel.id&&<div className=\"card\"><div className=\"row between\"><h2>Tarefas</h2><button className=\"btn primary\" onClick={draw}>Sortear</button></div><div className=\"grid\"><input className=\"input\" placeholder=\"Nova tarefa\" value={task.name} onChange={e=>setTask({...task,name:e.target.value})}/><select className=\"select\" value={task.period_key} onChange={e=>setTask({...task,period_key:e.target.value})}>{periods.map(x=><option key={x[0]} value={x[0]}>{x[1]}</option>)}</select><input className=\"input\" type=\"number\" min=\"1\" value={task.slots} onChange={e=>setTask({...task,slots:e.target.value})}/><select className=\"select\" value={task.category_id} onChange={e=>setTask({...task,category_id:e.target.value})}><option value=\"\">Categoria</option>{cats.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div><button className=\"btn\" onClick={addTask} disabled={!task.name.trim()}>Adicionar tarefa</button>{tasks.map(t=><div className=\"row between\" style={{padding:8,borderTop:\"1px solid var(--line)\"}} key={t.id}><span><b>{t.name}</b><small className=\"muted\"> · {t.task_categories?.name||\"Sem categoria\"} · {t.slots} vaga(s)</small></span><button className=\"btn\" onClick={()=>delTask(t.id)}><Trash2 size={14}/></button></div>)}</div>}</>}</>\n}\n'''
marker='function Admin('
if marker not in s: raise SystemExit('Admin marker not found')
s=s.replace(marker,editor+marker,1)
p.write_text(s,encoding='utf-8')
